// Lookup: item name -> primary game Category. Falls back to prefix matching so
// the favorites data's collapsed names ("Wing Fossil", "Music mat", "Meteor
// lamps") still resolve to a category.
const ITEM_PRIMARY_CATEGORY = (() => {
  const exact = new Map();
  for (const [cat, items] of Object.entries(ITEM_CATEGORIES)) {
    for (const it of items) exact.set(it, cat);
  }

  const result = {};
  // Walk every item that ever shows up in the favorites data.
  const allFavoriteItems = new Set();
  for (const data of Object.values(CATEGORIES)) {
    for (const it of data.items) allFavoriteItems.add(it);
  }

  for (const item of allFavoriteItems) {
    if (exact.has(item)) {
      result[item] = exact.get(item);
      continue;
    }
    // Prefix fallback (e.g. "Wing Fossil" -> "Wing Fossil (head)" -> Decoration)
    let matched = null;
    for (const cat of ITEM_CATEGORY_ORDER) {
      if (matched) break;
      const prefix = item.toLowerCase();
      for (const it of ITEM_CATEGORIES[cat]) {
        const lc = it.toLowerCase();
        if (lc.startsWith(prefix + ' ') || lc.startsWith(prefix + '(') || lc.startsWith(prefix.replace(/s$/, '') + ' ') || lc.startsWith(prefix.replace(/s$/, '') + '(')) {
          matched = cat;
          break;
        }
      }
    }
    result[item] = matched || 'Uncategorized';
  }
  return result;
})();

// Build inverted index: pokemon -> list of categories they have as a favorite
const POKEMON = {};
for (const [categoryName, data] of Object.entries(CATEGORIES)) {
  for (const pokemonName of data.pokemon) {
    if (!POKEMON[pokemonName]) POKEMON[pokemonName] = [];
    if (!POKEMON[pokemonName].includes(categoryName)) {
      POKEMON[pokemonName].push(categoryName);
    }
  }
}

// Sorted list of every pokemon known to Pokopia (per Serebii data)
const POKEMON_LIST = Object.keys(POKEMON).sort();
